<script>
const childrenByCustomer=@json($childrenByCustomer);let step=1;const form=document.getElementById('bookingWizardForm'),customer=document.getElementById('wizardCustomer'),child=document.getElementById('wizardChild'),sessionInput=document.getElementById('wizardSession');function showStep(n){step=n;document.querySelectorAll('[data-pane]').forEach(x=>x.classList.toggle('active',+x.dataset.pane===n));document.querySelectorAll('[data-step-indicator]').forEach(x=>x.classList.toggle('active',+x.dataset.stepIndicator===n));document.getElementById('wizardBack').classList.toggle('d-none',n===1);document.getElementById('wizardNext').classList.toggle('d-none',n===4);document.getElementById('wizardSubmit').classList.toggle('d-none',n!==4);if(n===4)fillConfirm()}
customer?.addEventListener('change',()=>{child.innerHTML='<option value="">Select player</option>';(childrenByCustomer[customer.value]||[]).forEach(c=>child.insertAdjacentHTML('beforeend',`<option value="${c.id}">${c.name}${c.meta?' — '+c.meta:''}</option>`))});document.querySelectorAll('[name="child_mode"]').forEach(r=>r.addEventListener('change',()=>{document.getElementById('existingPlayerBox').classList.toggle('d-none',r.value==='new'&&r.checked);document.getElementById('newPlayerBox').classList.toggle('d-none',!(r.value==='new'&&r.checked));document.querySelectorAll('[name="child_mode"]').forEach(x=>x.closest('.choice-card').classList.toggle('active',x.checked))}));document.querySelectorAll('.session-option').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.full==='1')return;document.querySelectorAll('.session-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');sessionInput.value=el.dataset.session;document.getElementById('allowExpired').value=el.dataset.expired==='1'?'1':'0'}));document.getElementById('wizardBack').onclick=()=>showStep(Math.max(1,step-1));document.getElementById('wizardNext').onclick=()=>{if(step===1&&!customer.value)return alert('Select a customer.');if(step===2){const mode=form.querySelector('[name="child_mode"]:checked').value;if(mode==='existing'&&!child.value)return alert('Select a player.');if(mode==='new'&&!form.querySelector('[name="player_first"]').value.trim())return alert('Enter the player first name.')}if(step===3&&!sessionInput.value)return alert('Select a session.');showStep(Math.min(4,step+1))};function fillConfirm(){document.getElementById('confirmCustomer').textContent=customer.options[customer.selectedIndex]?.text||'—';const mode=form.querySelector('[name="child_mode"]:checked').value;document.getElementById('confirmPlayer').textContent=mode==='existing'?(child.options[child.selectedIndex]?.text||'—'):`${form.querySelector('[name="player_first"]').value} ${form.querySelector('[name="player_last"]').value}`;const selected=document.querySelector(`.session-option[data-session="${sessionInput.value}"]`);document.getElementById('confirmSession').textContent=selected?.innerText.replace(/\s+/g,' ')||'—'}
form?.addEventListener('submit',async e=>{e.preventDefault();const box=document.getElementById('wizardValidation');box.className='alert alert-light border mt-3';box.textContent='Validating booking...';try{const res=await fetch('{{ route('admin.bookings.session-wise.manual.validate') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body:new FormData(form)});const data=await res.json();if(!res.ok){box.className='alert alert-danger mt-3';box.textContent=data.message||'Booking validation failed.';return}box.className='alert alert-success mt-3';box.textContent=data.message||'Booking is valid.';setTimeout(()=>HTMLFormElement.prototype.submit.call(form),250)}catch(err){box.className='alert alert-danger mt-3';box.textContent='Could not validate booking.'}});
</script>
@endpush
